package ama.transcript;
import ama.meeting.*;import ama.access.MeetingAccess;import ama.contract.IdentityContracts.*;import ama.db.TransactionRunner;import ama.task.*;import java.sql.*;import java.util.*;import javax.sql.DataSource;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real owner gate, transaction and combined registration; JDBC responses are offline substitutes. */
class Task12WorkspaceTasksTest {
 static final String M="00000000-0000-4000-8000-000000000001";
 DataSource ds;TransactionRunner tx;JdbcMeetingAccess access;JdbcTranscriptAuthority authority;JdbcTaskQueue queue;JdbcWorkspaceTasks reader;List<String> sql;boolean disabled;String owner="owner";List<Map<String,Object>> taskRows;Map<String,Map<String,Object>> parents;boolean changeTask;
 static final String T="00000000-0000-4000-8000-000000000002",I="00000000-0000-4000-8000-000000000003",B="00000000-0000-4000-8000-000000000004",C="00000000-0000-4000-8000-000000000005";
 static Map<String,Object> row(Object...v){var r=new LinkedHashMap<String,Object>();for(int i=0;i<v.length;i+=2)r.put((String)v[i],v[i+1]);return r;}
 @BeforeEach void setup()throws Exception{
  sql=new ArrayList<>();taskRows=new ArrayList<>();parents=new HashMap<>();ds=mock(DataSource.class);when(ds.getConnection()).thenAnswer(call->{var c=mock(Connection.class);when(c.getAutoCommit()).thenReturn(true);when(c.createStatement()).thenReturn(mock(Statement.class));when(c.prepareStatement(anyString())).thenAnswer(q->{String text=q.getArgument(0);sql.add(text);var statement=mock(PreparedStatement.class);when(statement.getConnection()).thenReturn(c);var args=new HashMap<Integer,Object>();doAnswer(a->{args.put(a.getArgument(0),a.getArgument(1));return null;}).when(statement).setString(anyInt(),anyString());when(statement.executeQuery()).thenAnswer(x->result(rows(text,args)));return statement;});return c;});
  tx=new TransactionRunner(ds);var fences=mock(SubjectFencePort.class);var subject=mock(SubjectFencePort.LockedSubject.class);when(subject.businessVersion()).thenReturn(9007199254740993L);when(fences.lock(any(),eq(false))).thenReturn(Optional.of(subject));access=new JdbcMeetingAccess(ds,tx,fences);
  var archive=new ama.contract.ConfigArchiveContracts.ArchiveReadBudget(65536,16777216,64,128,128,2000000,128,255,4194304,4194304,16777216,65536,64,100000,500000);var canonical=new ama.contract.MinutesContracts.CanonicalBudget(67108864,128,4000000,4194304,16777216);
  var components=JdbcTranscriptAuthority.create(ds,tx,access,(a,m,p)->{},mock(ama.storage.FileBackendCatalog.class),Map.of(),archive,canonical);authority=components.authority();queue=TranscriptImportRuntime.install(ds,new JdbcSubjectFences(ds,Set.of("MEETING")),new JdbcOutbox(ds,Map.of()),components);reader=new JdbcWorkspaceTasks(authority,queue,new WorkspaceCursor(),WorkspaceReadBudget.DEFAULT);
 }
 List<Map<String,Object>> rows(String query,Map<Integer,Object> args){if(query.contains(" FROM enterprise_identity "))return List.of(query.startsWith("SELECT status")?row("status",disabled?"DISABLED":"ACTIVE"):row("enterprise_id","owner","status",disabled?"DISABLED":"ACTIVE"));if(query.contains(" FROM meeting "))return List.of(row("id",M,"owner_id",owner,"revision",9007199254740993L,"access_revision",7L,"cancel_epoch",0L,"stage","PUBLISHED","lifecycle","ACTIVE","governance_state","ACTIVE","ever_published",true,"info_revision_id",null,"roster_revision_id",null));if(query.contains(" FROM durable_task ")){if(query.contains(" WHERE id=?")){var found=taskRows.stream().filter(row->Objects.equals(row.get("id"),args.get(1))).map(HashMap::new).toList();if(changeTask&&!found.isEmpty())found.getFirst().put("state","FAILED");return new ArrayList<>(found);}return taskRows;}for(var entry:parents.entrySet())if(query.contains(" FROM "+entry.getKey()+" "))return List.of(entry.getValue());throw new AssertionError(query);}
 ResultSet result(List<Map<String,Object>> rows)throws Exception{var rs=mock(ResultSet.class);var index=new java.util.concurrent.atomic.AtomicInteger(-1);var columns=rows.isEmpty()?List.<String>of():new ArrayList<>(rows.getFirst().keySet());var metadata=mock(ResultSetMetaData.class);when(metadata.getColumnCount()).thenReturn(columns.size());when(rs.getMetaData()).thenReturn(metadata);when(rs.next()).thenAnswer(x->index.incrementAndGet()<rows.size());when(rs.getString(anyInt())).thenAnswer(x->(String)rows.get(index.get()).get(columns.get((int)x.getArgument(0)-1)));when(rs.getString(anyString())).thenAnswer(x->(String)rows.get(index.get()).get(x.getArgument(0)));when(rs.getLong(anyString())).thenAnswer(x->((Number)rows.get(index.get()).get(x.getArgument(0))).longValue());when(rs.getBoolean(anyString())).thenAnswer(x->Boolean.TRUE.equals(rows.get(index.get()).get(x.getArgument(0))));when(rs.getObject(anyString())).thenAnswer(x->rows.get(index.get()).get(x.getArgument(0)));when(rs.getObject(anyString(),eq(java.time.LocalDateTime.class))).thenAnswer(x->rows.get(index.get()).get(x.getArgument(0)));return rs;}
 Actor actor(){return new Actor("owner",Status.ACTIVE,Set.of(Role.USER));}
 @Test void publishedOwnerCanReadEmptyHistoryThroughExactlyOneGate(){var page=reader.read(actor(),M,"ALL",20,null);assertTrue(page.items().isEmpty());assertFalse(page.hasMore());assertNull(page.nextCursor());assertEquals("PERSISTED_RELATION",page.verification());assertEquals(1,sql.stream().filter(q->q.startsWith("SELECT enterprise_id,status")).count());assertTrue(sql.stream().allMatch(q->q.startsWith("SELECT ")));}
 @Test void memberOrAdministratorIsRejectedBeforeAnyTaskRead(){owner="other";assertThrows(MeetingAccess.AccessDeniedException.class,()->reader.read(actor(),M,"ALL",20,null));assertTrue(sql.stream().noneMatch(q->q.contains("durable_task")));assertThrows(MeetingAccess.AccessDeniedException.class,()->reader.read(new Actor("owner",Status.ACTIVE,Set.of(Role.PLATFORM_ADMIN)),M,"ALL",20,null));}
 @Test void disabledActorAndBudgetFailureCannotAcquireTaskMetadata(){disabled=true;assertThrows(MeetingAccess.AccessDeniedException.class,()->reader.read(actor(),M,"ALL",20,null));assertTrue(sql.stream().noneMatch(q->q.contains("durable_task")));sql.clear();reader=new JdbcWorkspaceTasks(authority,queue,new WorkspaceCursor(),new WorkspaceReadBudget.Limits(1,1,1,1,1,1,java.time.Duration.ofSeconds(5)));assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor(),M,"ALL",20,null));assertTrue(sql.isEmpty());}
 @Test void ambientTransactionAndUnregisteredQueueAreRejected(){assertThrows(WorkspaceReadBudget.Unavailable.class,()->tx.required(()->reader.read(actor(),M,"ALL",20,null)));assertThrows(IllegalArgumentException.class,()->new JdbcWorkspaceTasks(authority,new JdbcTaskQueue(ds,new JdbcSubjectFences(ds,Set.of("MEETING")),new JdbcOutbox(ds,Map.of()),Map.of()),new WorkspaceCursor(),WorkspaceReadBudget.DEFAULT));assertTrue(sql.isEmpty());}
 @Test void cursorCannotCrossActorMeetingOrKind(){var cursors=new WorkspaceCursor();reader=new JdbcWorkspaceTasks(authority,queue,cursors,WorkspaceReadBudget.DEFAULT);String cursor=cursors.encode("different","tasks:"+M+":ALL","2026-10-27T00:00:00.000000|"+M);assertThrows(IllegalArgumentException.class,()->reader.read(actor(),M,"ALL",20,cursor));assertTrue(sql.isEmpty());}

 void importTask(){taskRows.add(row("id",T,"task_type","TRANSCRIPT_IMPORT_V1","pool","TRANSCRIPT_IMPORT","subject_kind","MEETING","subject_id",M,"producer_key","a".repeat(64),"input_kind","TRANSCRIPTION_INPUT","input_id",I,"input_fingerprint","b".repeat(64),"business_version",7L,"priority",0L,"cancel_epoch",0L,"max_attempts",3L,"state","SUCCEEDED","attempt",1L,"created_at",java.time.LocalDateTime.of(2026,10,27,0,0)));parents.put("transcription_input",row("id",I,"meeting_id",M,"batch_id",B,"kind","IMPORT","material_mode","EMPTY","material_snapshot_id",null,"source_revision_id",null,"model_config_version",null,"prompt_version",null,"parser_version","v1","manifest_schema_version",1L,"input_fingerprint","b".repeat(64),"base_revision",7L,"cancel_epoch",0L));parents.put("input_batch",row("id",B,"meeting_id",M,"kind","TRANSCRIPT","base_revision",7L));parents.put("input_batch_fingerprint_profile",row("batch_id",B,"profile","ama.input-batch.v1"));}
 @Test void realOwnerReadReturnsHistoricalTaskOnlyAfterParentLocksAndExactTaskRecheck(){importTask();var page=reader.read(actor(),M,"ALL",20,null);assertEquals(T,page.items().getFirst().taskId());assertEquals("7",page.items().getFirst().businessRevisionToken());assertEquals("/api/v1/meetings/"+M+"/processing-tasks/"+T,page.items().getFirst().detailPath());int task=-1;for(int i=0;i<sql.size();i++)if(sql.get(i).contains(" FROM durable_task WHERE id="))task=i;assertTrue(task>0);for(int i=task+1;i<sql.size();i++)assertFalse(sql.get(i).endsWith("FOR UPDATE"));assertTrue(sql.stream().anyMatch(q->q.contains("input_batch_fingerprint_profile")&&q.endsWith("FOR UPDATE")));}
 @Test void changedTaskAndDanglingParentNeverProduceAUsablePage(){importTask();changeTask=true;assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor(),M,"ALL",20,null));changeTask=false;parents.get("input_batch").put("meeting_id",C);assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor(),M,"ALL",20,null));}
 @Test void heldCompositionRejectsForeignAndExpiredGatesAndRepeatedFinish(){assertThrows(IllegalArgumentException.class,()->tx.required(()->reader.captureHeld(actor(),M,"ALL",20,null,mock(ama.storage.FileRegistry.LockedMeeting.class),new WorkspaceReadBudget())));var plan=tx.required(()->{var gate=authority.fileRegistry().lock(actor(),M,MeetingAccess.Action.EDIT);return reader.captureHeld(actor(),M,"ALL",20,null,gate,new WorkspaceReadBudget());});assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.lockParents(plan));tx.required(()->{var gate=authority.fileRegistry().lock(actor(),M,MeetingAccess.Action.EDIT);var held=reader.captureHeld(actor(),M,"ALL",20,null,gate,new WorkspaceReadBudget());reader.lockParents(held);reader.finish(held);assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.finish(held));return null;});}

 @Test void mixedFamiliesLockAllParentsBeforeAnyTaskAndFilteredPageAdvancesScannedRows(){importTask();var publication=new HashMap<>(taskRows.getFirst());publication.put("id",C);publication.put("task_type","KNOWLEDGE_PUBLISH_V1");publication.put("pool","KNOWLEDGE_PUBLISH");publication.put("input_kind","PUBLICATION");taskRows.addFirst(publication);parents.put("publication",row("id",I,"meeting_id",M));parents.put("final_confirmation",row("id",B,"meeting_id",M));parents.put("publication_submission",row("task_id",C,"publication_id",I,"confirmation_id",B,"submission_no",1L,"logical_request_hash","b".repeat(64),"business_key",I+":"+B));var cursors=new WorkspaceCursor();reader=new JdbcWorkspaceTasks(authority,queue,cursors,WorkspaceReadBudget.DEFAULT);
  var page=reader.read(actor(),M,"MINUTES_GENERATE_V1",1,null);assertTrue(page.items().isEmpty());assertTrue(page.hasMore());assertEquals("2026-10-27T00:00:00.000000|"+C,cursors.decode("owner","tasks:"+M+":MINUTES_GENERATE_V1",page.nextCursor()));assertThrows(IllegalArgumentException.class,()->reader.read(actor(),M,"ALL",1,page.nextCursor()));
  var locks=sql.stream().filter(q->q.endsWith("FOR UPDATE")&&!q.contains(" FROM meeting ")&&!q.contains("enterprise_identity")).toList();int firstTask=-1;for(int n=0;n<locks.size();n++)if(locks.get(n).contains(" FROM durable_task ")){firstTask=n;break;}assertTrue(firstTask>=6);assertTrue(locks.subList(firstTask,locks.size()).stream().allMatch(q->q.contains(" FROM durable_task ")));assertTrue(locks.getFirst().contains(" FROM publication "));assertTrue(locks.get(1).contains(" FROM final_confirmation "));assertTrue(locks.get(2).contains(" FROM publication_submission "));
 }

 @Test void realAccessFromAnotherDataSourceCannotAuthorizeThisReadersTaskRows(){var foreign=mock(DataSource.class);var foreignTx=new TransactionRunner(foreign);var otherAccess=new JdbcMeetingAccess(foreign,foreignTx,mock(SubjectFencePort.class));var components=JdbcTranscriptAuthority.create(ds,tx,otherAccess,(a,m,p)->{},mock(ama.storage.FileBackendCatalog.class),Map.of(),authority.readBudget(),authority.canonicalBudget());var otherQueue=TranscriptImportRuntime.install(ds,new JdbcSubjectFences(ds,Set.of("MEETING")),new JdbcOutbox(ds,Map.of()),components);assertThrows(IllegalArgumentException.class,()->new JdbcWorkspaceTasks(components.authority(),otherQueue,new WorkspaceCursor(),WorkspaceReadBudget.DEFAULT));assertTrue(sql.isEmpty());verifyNoInteractions(foreign);}
}
